style.css:
@-moz-document domain("reddit.com") {
/* Purreddit - Catpuccin Mocha Reddit Theme */

/* Main Background */
body, html {
    background-color: #1e1e2e !important;
    color: #cdd6f4 !important;
}

/* Header */
header[role="banner"], 
.Header,
#header {
    background-color: #181825 !important;
    border-bottom: 1px solid #313244 !important;
}

/* Navigation */
.header-user-dropdown,
.dropdown-menu {
    background-color: #313244 !important;
    border: 1px solid #45475a !important;
}

/* Sidebar */
.side,
.listing-chooser,
.subreddit-info,
.sidebar {
    background-color: #181825 !important;
    border: 1px solid #313244 !important;
}

/* Posts */
.thing,
.Post,
.link,
.comment {
    background-color: #313244 !important;
    border: 1px solid #45475a !important;
    color: #cdd6f4 !important;
}

.thing:hover,
.Post:hover {
    background-color: #45475a !important;
}

/* Post titles */
.title a,
.Post h3 a {
    color: #89b4fa !important;
}

.title a:visited,
.Post h3 a:visited {
    color: #cba6f7 !important;
}

.title a:hover,
.Post h3 a:hover {
    color: #89dceb !important;
}

/* Vote arrows */
.arrow.up {
    border-bottom-color: #fab387 !important;
}

.arrow.upmod {
    border-bottom-color: #fab387 !important;
}

.arrow.down {
    border-top-color: #89b4fa !important;
}

.arrow.downmod {
    border-top-color: #89b4fa !important;
}

/* Comments */
.comment .md {
    color: #cdd6f4 !important;
}

.comment .author {
    color: #a6e3a1 !important;
}

.comment .author.moderator {
    color: #f38ba8 !important;
}

.comment .author.submitter {
    color: #f9e2af !important;
}

/* Comment score */
.score.likes {
    color: #fab387 !important;
}

.score.dislikes {
    color: #89b4fa !important;
}

/* Buttons */
button,
.btn,
input[type="submit"] {
    background-color: #45475a !important;
    border: 1px solid #585b70 !important;
    color: #cdd6f4 !important;
}

button:hover,
.btn:hover,
input[type="submit"]:hover {
    background-color: #585b70 !important;
    color: #b4befe !important;
}

/* Links */
a {
    color: #89b4fa !important;
}

a:hover {
    color: #89dceb !important;
}

a:visited {
    color: #cba6f7 !important;
}

/* Subreddit links */
.subreddit {
    color: #94e2d5 !important;
}

/* Username links */
.author {
    color: #a6e3a1 !important;
}

/* Text inputs */
input[type="text"],
input[type="password"],
textarea,
.md-container textarea {
    background-color: #313244 !important;
    border: 1px solid #45475a !important;
    color: #cdd6f4 !important;
}

input[type="text"]:focus,
input[type="password"]:focus,
textarea:focus {
    border-color: #89b4fa !important;
    box-shadow: 0 0 5px #89b4fa !important;
}

/* Search */
.search-form input[type="text"] {
    background-color: #313244 !important;
    border: 1px solid #45475a !important;
    color: #cdd6f4 !important;
}

/* Flair */
.flair,
.linkflair {
    background-color: #45475a !important;
    color: #f9e2af !important;
    border: 1px solid #585b70 !important;
}

/* Messages/Notifications */
.message,
.mail {
    background-color: #313244 !important;
    border: 1px solid #45475a !important;
}

.message.unread {
    background-color: #45475a !important;
    border-left: 3px solid #f9e2af !important;
}

/* Dropdown menus */
.drop-choices {
    background-color: #313244 !important;
    border: 1px solid #45475a !important;
}

.choice:hover {
    background-color: #45475a !important;
}

/* Code blocks */
code,
pre {
    background-color: #11111b !important;
    color: #cdd6f4 !important;
    border: 1px solid #313244 !important;
}

/* Blockquotes */
blockquote {
    border-left: 3px solid #89b4fa !important;
    background-color: #313244 !important;
    color: #bac2de !important;
}

/* Tables */
table {
    background-color: #313244 !important;
    border: 1px solid #45475a !important;
}

th, td {
    border: 1px solid #45475a !important;
    color: #cdd6f4 !important;
}

th {
    background-color: #45475a !important;
}

/* New Reddit compatibility */
._3Im6OD67aKo33nql4FpSp_ {
    background-color: #1e1e2e !important;
}

._1YWnD_dOJZtarticleContainer {
    background-color: #313244 !important;
}

._25IkBM0rRUqWX5ZojEMAFQ {
    color: #cdd6f4 !important;
}

/* RES compatibility */
.RES-keyNav-activeElement {
    background-color: #45475a !important;
    border: 2px solid #89b4fa !important;
}

.res-nightmode .entry {
    background-color: #313244 !important;
}
}
